function printDoc(which){const old=$('rsPrintDocument');if(old)old.remove();const root=document.createElement('section');root.id='rsPrintDocument';root.className=which==='resume'?'rs-print-resume':'rs-print-cover';if(which==='resume'){const source=$('resumePreview');const clone=source.cloneNode(true);clone.removeAttribute('id');clone.classList.add('rs-print-paper');root.appendChild(clone)}else{const page=document.createElement('article');page.className='rs-print-cover-page';const content=$('coverLetter').value.trim();const paragraphs=content.split(/\\n\\s*\\n/).map(s=>s.trim()).filter(Boolean);paragraphs.forEach(block=>{const p=document.createElement('p');p.textContent=block;page.appendChild(p)});root.appendChild(page)}document.body.appendChild(root);document.body.dataset.printDoc=which;window.print();setTimeout(()=>{root.remove();delete document.body.dataset.printDoc},1000)}
