// Render actual template thumbnails and structured verification forms for contact, experience, and education.\nrenderWizard=function(){const stage=wizardStages[wizardStep];$('wizardTitle').textContent=stage.title;$('wizardDescription').textContent=stage.description;$('wizardTip').textContent=stage.tip;$('wizardStepLabel').textContent='Step '+(wizardStep+1)+' of '+wizardStages.length;$('wizardPrevious').hidden=wizardStep===0;$('wizardContinue').textContent=wizardStep===wizardStages.length-1?'Save changes':'Save and continue →';$('wizardProgress').innerHTML=wizardStages.map((s,i)=>'<span class="rs-wizard-dot '+(i<wizardStep?'is-complete':i===wizardStep?'is-active':'')+'" aria-label="'+escapeHtml(s.title)+'">'+(i<wizardStep?'✓':i+1)+'</span>').join('<i></i>');const root=$('wizardForm');root.innerHTML='';if(stage.kind==='template'){const select=$('resumeTemplate').value||'new-york';const options=[['new-york','New York','Clean & ATS-friendly'],['paris','Paris','Editorial'],['toronto','Toronto','Structured'],['chicago','Chicago','Bold hierarchy'],['london','London','Traditional'],['boston','Boston','Minimal accent'],['madrid','Madrid','Color accents'],['santiago','Santiago','Color-block header'],['seattle','Seattle','Contemporary'],['stockholm','Stockholm','Minimal'],['tokyo','Tokyo','Compact'],['istanbul','Istanbul','Warm neutral'],['sydney','Sydney','Soft neutral'],['sao-paulo','São Paulo','Editorial serif'],['seoul','Seoul','Blue accent'],['berlin','Berlin','Modern grid'],['mexico-city','Mexico City','Distinctive'],['dubai','Dubai','Side accent'],['zurich','Zurich','Balanced'],['vienna','Vienna','Classic']];const preview=$('resumePreview');root.innerHTML='<div class="rs-template-choices">'+options.map(([id,name,desc])=>'<button type="button" class="rs-template-choice '+(id===select?'is-selected':'')+'" data-template-choice="'+id+'"><span class="rs-template-preview-frame"><span class="rs-template-placeholder"></span></span><strong>'+name+'</strong><small>'+desc+'</smal